<script setup lang="ts">import {computed} from 'vue';import type {SpatialPoint,Prediction} from '../types/domain';import {fixed} from '../utils/format';const props=withDefaults(defineProps<{points:SpatialPoint[];predictions?:Prediction[];mode?:'value'|'sd';selected?:string}>(),{predictions:()=>[],mode:'value',selected:''});const emit=defineEmits<{select:[id:string]}>();const bounds=computed(()=>{const rows=[...props.points,...props.predictions],x=rows.map(r=>r.x),y=rows.map(r=>r.y),a=Math.min(...x),b=Math.max(...x),c=Math.min(...y),d=Math.max(...y);return {xmin:a-Math.max((b-a)*.08,.2),xmax:b+Math.max((b-a)*.08,.2),ymin:c-Math.max((d-c)*.08,.2),ymax:d+Math.max((d-c)*.08,.2)}});const limits=computed(()=>{const values=props.mode==='sd'?props.predictions.map(p=>p.standard_deviation):[...props.points.map(p=>p.value),...props.predictions.map(p=>p.prediction)];return {min:Math.min(...values,props.mode==='sd'?0:Infinity),max:Math.max(...values)}});const X=(v:number)=>55+(v-bounds.value.xmin)/(bounds.value.xmax-bounds.value.xmin)*570;const Y=(v:number)=>365-(v-bounds.value.ymin)/(bounds.value.ymax-bounds.value.ymin)*325;function color(v:number){const r=(v-limits.value.min)/Math.max(limits.value.max-limits.value.min,.001);return `oklch(${87-r*42}% ${.04+r*.045} ${105+r*20})`}</script><template><div class="spatial-map"><svg viewBox="0 0 680 425" role="img" :aria-label="mode==='sd'?'待估点空间标准差图':'采样与含水预测局部平面图'"><g v-for="t in [0,.25,.5,.75,1]" :key="t"><line :x1="55+t*570" :x2="55+t*570" y1="40" y2="365" class="map-grid"/><line x1="55" x2="625" :y1="40+t*325" :y2="40+t*325" class="map-grid"/><text :x="55+t*570" y="387" text-anchor="middle">{{fixed(bounds.xmin+t*(bounds.xmax-bounds.xmin),0)}}</text><text x="8" :y="44+t*325">{{fixed(bounds.ymax-t*(bounds.ymax-bounds.ymin),0)}}</text></g><circle v-for="p in points" :key="p.point_id" :cx="X(p.x)" :cy="Y(p.y)" r="4.5" :fill="mode==='value'?color(p.value):'oklch(75% .012 100)'" class="sample-point"><title>{{p.point_id}} · {{fixed(p.value)}}%</title></circle><rect v-for="p in predictions" :key="p.query_id" :x="X(p.x)-6" :y="Y(p.y)-6" width="12" height="12" :fill="color(mode==='sd'?p.standard_deviation:p.prediction)" :class="['query-point',{selected:p.query_id===selected}]" @click="emit('select',p.query_id)"><title>{{p.query_id}} · 预测{{fixed(p.prediction)}}% · 空间SD{{fixed(p.standard_deviation)}}</title></rect><text x="340" y="416" text-anchor="middle">局部平面 x / 米 · 纵轴 y / 米</text></svg><div class="map-legend"><span>● 采样点</span><span>■ 待估点（可点选）</span><span>色阶 {{fixed(limits.min,2)}}—{{fixed(limits.max,2)}} {{mode==='sd'?'空间SD/百分点':'含水率/%'}}</span></div></div></template>
